import static java.lang.System.out;public class NoSunshine{public static void main(String[] args){String a="Ain't no sunshine when she's gone";String b="And this house just ain't no home";String c="Anytime she goes away";C(a,"It's not warm when she's away","And she's always gone too long",c,a);C("Wonder this time where she's gone", "Wonder if she's gone to stay",b,c,a);I();out.println("Hey, I ought to leave young thing alone\nBut "+a+", whoa-whoa");C(a,"Only darkness every day\n",b,c,a);for(int i=0;i<3;i++){out.println(c);}}public static void I(){out.print("And ");for(int i=0;i<5;i++){for(int j=0;j<4;j++){out.print("I know, ");}out.println("I know");}out.println("I know, I know\n");}public static void C(String v,String w,String x,String y, String z){String n="\n";out.println(v+n+w+n+z+n+x+n+y+n);}}